refentry.refsect1:
&reftitle.description;
&style.oop; intstringmysqli_stmt->insert_id
&style.procedural;
intstringmysqli_stmt_insert_id mysqli_stmtstatement
Retorna o ID gerado por uma instrução INSERT ou UPDATE em uma tabela com uma coluna que tenha o atributo AUTO_INCREMENT. No caso de uma instrução INSERT com várias linhas, retorna o primeiro valor gerado automaticamente que foi inserido com sucesso. Se LAST_INSERT_ID(expr) for usado para definir o valor de AUTO_INCREMENT, ou em um UPDATE, o valor de expr será retornado em vez disso.
Retorna 0 se a instrução não alterou um valor de AUTO_INCREMENT.

  &reftitle.examples;

   Exemplo de mysqli_stmt::$insert_id
   &style.oop;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$mysqli = new mysqli("localhost", "my_user", "my_password", "world");

$mysqli->query("CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = $mysqli->prepare("INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
$stmt->bind_param('sssi', $name, $countryCode, $district, $population);
$stmt->execute();

printf("O novo registro tem ID %d.\n", $stmt->insert_id);


   &style.procedural;


<?php

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
$link = mysqli_connect("localhost", "my_user", "my_password", "world");

mysqli_query($link, "CREATE TEMPORARY TABLE myCity LIKE City");

$stmt = mysqli_prepare($link, "INSERT INTO myCity (Name, CountryCode, District, Population) VALUES (?, ?, ?, ?)");

$name = 'Stuttgart';
$countryCode = 'DEU';
$district = 'Stuttgart';
$population = 617000;
mysqli_stmt_bind_param($stmt, 'sssi', $name, $countryCode, $district, $population);
mysqli_stmt_execute($stmt);

printf("O novo registro tem ID %d.\n", mysqli_stmt_insert_id($stmt));


   &examples.outputs;


O novo registro tem ID 1.
